//! `kernel.tensors.linear` weight formats Q4_1, Q5_1, Q5_K, F16 and BF16, checked against values
//! the Python `gguf` package dequantizes the same raw blocks to (`tests/fixtures/gguf_quant`,
//! regenerated by boring-llm's `tools/make_quant_test_fixtures.py`).

use std::fs;
use std::path::PathBuf;
use std::process::Command;

struct Case {
    format: &'static str,
    /// Elements in the fixture; the weight matrix is `n` rows of `k`.
    n: usize,
    k: usize,
}

const CASES: [Case; 5] = [
    Case { format: "q4_1", n: 3, k: 32 },
    Case { format: "q5_1", n: 3, k: 32 },
    Case { format: "q5_k", n: 3, k: 256 },
    Case { format: "f16", n: 2, k: 32 },
    Case { format: "bf16", n: 2, k: 32 },
];

fn fixture(name: &str) -> Vec<u8> {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/gguf_quant").join(name);
    fs::read(&path).unwrap_or_else(|error| panic!("{}: {error}", path.display()))
}

fn expected_and_source(case: &Case, with_bias: bool, m: usize) -> (Vec<f32>, String) {
    let packed = fixture(&format!("quant-{}.bin", case.format));
    let decoded: Vec<f32> = fixture(&format!("quant-{}.f32", case.format))
        .chunks_exact(4)
        .map(|bytes| f32::from_le_bytes(bytes.try_into().unwrap()))
        .collect();
    assert_eq!(decoded.len(), case.n * case.k);
    let x: Vec<f32> = (0..m * case.k).map(|index| ((index * 5) % 11) as f32 * 0.25 - 1.25).collect();
    let bias: Vec<f32> = (0..case.n).map(|col| col as f32 - 0.5).collect();
    let mut expected = Vec::new();
    for row in 0..m {
        for col in 0..case.n {
            let mut sum = if with_bias { bias[col] as f64 } else { 0.0 };
            for inner in 0..case.k {
                sum += x[row * case.k + inner] as f64 * decoded[col * case.k + inner] as f64;
            }
            expected.push(sum as f32);
        }
    }
    let floats = x.iter().map(|value| format!("{value} as float32")).collect::<Vec<_>>().join(", ");
    let bytes = packed.iter().map(|value| format!("uint8({value})")).collect::<Vec<_>>().join(", ");
    let bias_floats = bias.iter().map(|value| format!("{value} as float32")).collect::<Vec<_>>().join(", ");
    let outputs = m * case.n;
    let (bias_param, bias_arg, bias_decl) = if with_bias {
        (", [float32]'kernel'global bias", "bias, ", format!("let [float32]'kernel'global bias = [{bias_floats}]\n"))
    } else {
        ("", "", String::new())
    };
    let call_bias = if with_bias { ", bias" } else { "" };
    let prints = (0..outputs).map(|i| format!("{{result[{i}]}}")).collect::<Vec<_>>().join(",");
    let source = format!(
        "req [float32]'kernel'unified compute([float32]'kernel'global x, [uint8]'kernel'global weight{bias_param}) throws:\n    mut [float32]'kernel'unified y = [0.0 as float32 for ..<{outputs}]\n    kernel.tensors.linear(x, weight, {bias_arg}y, m = {m}, n = {n}, k = {k}, format = \"{format}\")\n    y\n\nlet [float32]'kernel'global x = [{floats}]\nlet [uint8]'kernel'global weight = [{bytes}]\n{bias_decl}let result = compute(x, weight{call_bias})\nwith result:\n    print \"{prints}\"\n",
        n = case.n, k = case.k, format = case.format,
    );
    (expected, source)
}

fn close(actual: f32, expected: f32) -> bool {
    (actual - expected).abs() <= 1.0e-4 * (expected.abs() + 1.0)
}

#[test]
fn interpreter_matches_gguf_dequantize() {
    for case in &CASES {
        for with_bias in [false, true] {
            let (expected, source) = expected_and_source(case, with_bias, 3);
            let root = PathBuf::from(env!("CARGO_TARGET_TMPDIR")).join(format!("tensor_gguf_{}_{with_bias}", case.format));
            fs::create_dir_all(&root).unwrap();
            let path = root.join("reference.br");
            fs::write(&path, source).unwrap();
            let run = Command::new(env!("CARGO_BIN_EXE_boring")).arg("run").arg(&path).output().unwrap();
            assert!(run.status.success(), "{}: {}", case.format, String::from_utf8_lossy(&run.stderr));
            let actual: Vec<f32> = String::from_utf8_lossy(&run.stdout).trim().split(',').map(|v| v.parse().unwrap()).collect();
            assert_eq!(actual.len(), expected.len(), "{}", case.format);
            for (index, (a, e)) in actual.iter().zip(&expected).enumerate() {
                assert!(close(*a, *e), "{} bias={with_bias} output {index}: got {a}, expected {e}", case.format);
            }
        }
    }
}

#[test]
fn every_gpu_target_accepts_the_formats() {
    for case in &CASES {
        let (_, source) = expected_and_source(case, true, 3);
        let root = PathBuf::from(env!("CARGO_TARGET_TMPDIR")).join(format!("tensor_gguf_targets_{}", case.format));
        fs::create_dir_all(&root).unwrap();
        let path = root.join("reference.br");
        fs::write(&path, source).unwrap();
        for target in ["cuda", "metal", "rocm", "wgpu"] {
            let build = Command::new(env!("CARGO_BIN_EXE_boring")).args(["build", "--target", target]).arg(&path).output().unwrap();
            assert!(build.status.success(), "{} on {target}: {}", case.format, String::from_utf8_lossy(&build.stderr));
        }
    }
}

/// Real Metal: the native SIMD-group decode (m == 1) and blocked prefill (m > 1) kernels must
/// reproduce the same oracle values.
#[cfg(target_os = "macos")]
#[test]
fn metal_native_schedules_match_gguf_dequantize() {
    for case in &CASES {
        for (with_bias, m) in [(false, 1), (true, 1), (false, 3), (true, 3)] {
            let (expected, source) = expected_and_source(case, with_bias, m);
            let root = PathBuf::from(env!("CARGO_TARGET_TMPDIR")).join(format!("tensor_gguf_metal_{}_{with_bias}_{m}", case.format));
            let _ = fs::remove_dir_all(&root);
            fs::create_dir_all(&root).unwrap();
            fs::write(root.join("boring.toml"), format!("[project]\nname = \"gguf-{}\"\n\n[tensor.linear.prefill]\n{} = \"native\"\n", case.format.replace('_', "-"), case.format)).unwrap();
            let path = root.join("reference.br");
            fs::write(&path, source).unwrap();
            let build = Command::new(env!("CARGO_BIN_EXE_boring")).args(["build", "--target", "metal"]).arg(&path).output().unwrap();
            assert!(build.status.success(), "{}", String::from_utf8_lossy(&build.stderr));
            let cargo = Command::new("cargo")
                .args(["run", "--release", "--quiet", "--manifest-path"])
                .arg(root.join("reference_metal/Cargo.toml"))
                .env("CARGO_TERM_COLOR", "never")
                // One dependency build shared by every generated project.
                .env("CARGO_TARGET_DIR", PathBuf::from(env!("CARGO_TARGET_TMPDIR")).join("tensor_gguf_metal_shared_target"))
                .output()
                .unwrap();
            assert!(cargo.status.success(), "{}: {}", case.format, String::from_utf8_lossy(&cargo.stderr));
            let actual: Vec<f32> = String::from_utf8_lossy(&cargo.stdout).trim().split(',').map(|v| v.parse().unwrap()).collect();
            for (index, (a, e)) in actual.iter().zip(&expected).enumerate() {
                assert!(close(*a, *e), "{} metal m={m} bias={with_bias} output {index}: got {a}, expected {e}", case.format);
            }
        }
    }
}

/// The portable fallback: wgpu (here running on the Mac's GPU) executes the generic Boring-synthesized
/// decode and tiled-prefill kernels for the same weights.
#[cfg(target_os = "macos")]
#[test]
fn wgpu_portable_schedules_match_gguf_dequantize() {
    for case in &CASES {
        for m in [1, 3] {
            let (expected, source) = expected_and_source(case, true, m);
            let root = PathBuf::from(env!("CARGO_TARGET_TMPDIR")).join(format!("tensor_gguf_wgpu_{}_{m}", case.format));
            let _ = fs::remove_dir_all(&root);
            fs::create_dir_all(&root).unwrap();
            let path = root.join("reference.br");
            fs::write(&path, source).unwrap();
            let build = Command::new(env!("CARGO_BIN_EXE_boring")).args(["build", "--target", "wgpu"]).arg(&path).output().unwrap();
            assert!(build.status.success(), "{}", String::from_utf8_lossy(&build.stderr));
            let cargo = Command::new("cargo")
                .args(["run", "--release", "--quiet", "--manifest-path"])
                .arg(root.join("reference_wgpu/Cargo.toml"))
                .env("CARGO_TERM_COLOR", "never")
                .env("CARGO_TARGET_DIR", PathBuf::from(env!("CARGO_TARGET_TMPDIR")).join("tensor_gguf_wgpu_shared_target"))
                .output()
                .unwrap();
            assert!(cargo.status.success(), "{}: {}", case.format, String::from_utf8_lossy(&cargo.stderr));
            let actual: Vec<f32> = String::from_utf8_lossy(&cargo.stdout).trim().split(',').map(|v| v.parse().unwrap()).collect();
            assert_eq!(actual.len(), expected.len(), "{}", case.format);
            for (index, (a, e)) in actual.iter().zip(&expected).enumerate() {
                assert!(close(*a, *e), "{} wgpu m={m} output {index}: got {a}, expected {e}", case.format);
            }
        }
    }
}
